{{!-- Styling parameters: class, titleClass, gridClass, cardClass, contentClass --}}
{{#with this as |ghostcnStyles|}}
{{!-- Component: Featured Posts | Usage: {{> "components/featured-posts"}} --}}
{{#get "posts" filter="featured:true" limit="3" include="authors,tags"}}
{{#if posts}}
<section class="ghcn-featured{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}} ghcn-container" aria-label="Featured posts">
    <div class="ghcn-featured__heading">
        <div><span class="ghcn-badge">Featured</span><h2 class="ghcn-featured__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">Editor’s picks</h2></div>
        <a href="{{@site.url}}">View all posts <span aria-hidden="true">&rarr;</span></a>
    </div>
    <div class="ghcn-featured__grid{{#if ghostcnStyles.gridClass}} {{ghostcnStyles.gridClass}}{{/if}}">
        {{#foreach posts}}
        <article class="ghcn-featured__card{{#if ghostcnStyles.cardClass}} {{ghostcnStyles.cardClass}}{{/if}}{{#has index="0"}} ghcn-featured__card--lead{{/has}}">
            <a class="ghcn-featured__image" href="{{url}}">
                {{#if feature_image}}<img src="{{img_url feature_image size="l"}}" alt="{{#if feature_image_alt}}{{feature_image_alt}}{{else}}{{title}}{{/if}}" loading="{{#has index="0"}}eager{{else}}lazy{{/has}}" />{{/if}}
            </a>
            <div class="ghcn-featured__content{{#if ghostcnStyles.contentClass}} {{ghostcnStyles.contentClass}}{{/if}}">
                <div class="ghcn-featured__meta">{{#if primary_tag}}<a href="{{primary_tag.url}}">{{primary_tag.name}}</a><span>&bull;</span>{{/if}}<span>{{reading_time}}</span></div>
                <h3><a href="{{url}}">{{title}}</a></h3>
                {{#has index="0"}}{{#if excerpt}}<p>{{excerpt words="30"}}</p>{{/if}}{{/has}}
            </div>
        </article>
        {{/foreach}}
    </div>
</section>
{{/if}}
{{/get}}
{{/with}}

/* ghostcn: Featured Posts */
.ghcn-featured { box-sizing: border-box; margin-block: 3em; color: var(--foreground); font-family: inherit; font-size: 16px; line-height: 1.5; isolation: isolate; }
.ghcn-featured *, .ghcn-featured *::before, .ghcn-featured *::after { box-sizing: border-box; }
.ghcn-featured__heading { display: flex; align-items: end; justify-content: space-between; gap: 1em; margin-bottom: 1.25em; }
.ghcn-featured__heading h2 { margin: 0.75em 0 0; font-size: clamp(1.75em,4vw,2.5em); line-height: 1.05; letter-spacing: -0.04em; }
.ghcn-featured__heading > a { color: var(--muted-foreground); font-size: 0.875em; font-weight: 600; text-decoration: none; }
.ghcn-featured__grid { display: grid; grid-template-columns: minmax(0,2fr) minmax(15em,1fr); gap: 1em; }
.ghcn-featured__card { position: relative; min-height: 15em; overflow: hidden; border-radius: min(var(--radius),1.25em); background: var(--muted); }
.ghcn-featured__card--lead { grid-row: span 2; min-height: 31em; }
.ghcn-featured__image, .ghcn-featured__image::after { position: absolute; inset: 0; }
.ghcn-featured__image::after { content: ""; background: linear-gradient(to top,rgba(0,0,0,.82),rgba(0,0,0,.02) 70%); }
.ghcn-featured__image img { width: 100%; height: 100%; object-fit: cover; transition: transform .35s ease; }
.ghcn-featured__card:hover img { transform: scale(1.025); }
.ghcn-featured__content { position: absolute; right: 0; bottom: 0; left: 0; z-index: 1; padding: 1.25em; color: #fff; }
.ghcn-featured__card--lead .ghcn-featured__content { padding: 2em; }
.ghcn-featured__meta { display: flex; gap: 0.5em; margin-bottom: 0.5em; color: rgba(255,255,255,.78); font-size: 0.75em; }
.ghcn-featured__meta a, .ghcn-featured h3 a { color: inherit; text-decoration: none; }
.ghcn-featured h3 { margin: 0; font-size: 1.25em; line-height: 1.15; letter-spacing: -0.025em; }
.ghcn-featured__card--lead h3 { font-size: clamp(1.75em,4vw,3em); }
.ghcn-featured__content p { max-width: 42em; margin: 0.75em 0 0; color: rgba(255,255,255,.82); }
@media (max-width: 720px) { .ghcn-featured__grid { grid-template-columns: 1fr; } .ghcn-featured__card--lead { grid-row: auto; min-height: 25em; } }
